// TH15 v1.00b st04 道中 MainSub01 首组镜像直线激光扇（源 898-916）+ ECir01(105-139)/ECir01_at(141-175)。
// 源 caller 为关卡 main 的 MainFront（STAGE，坐标原点），故 enmCreate 相对坐标即世界坐标。

const TIME_LIMIT: int = 1124;
const OPENING_BUFFER: int = 120;

// 源 laserNew(0, 0, 128, 0, 16)：L=targetLength 128，宽 16（<32 → 半高 4）。
// Line 的 0x2 位未设 → 判定段 [0.1L, 0.9L]；w=16 → 目标判定宽 8。
const BEAM_NEAR: fx = 12.8fx;
const BEAM_FAR: fx = 115.2fx;
const BEAM_WIDTH: fx = 8fx;
const BEAM_COLOR: int = 4;          // etSprite(0, 8, 4) 的色号

// 源 etSpeed 0.4；etEx WAIT(60) 后 ACCEL(a=120, r=0.1, s=-999999 保留当前角)。
const BEAM_SPEED: fx = 0.4fx;
const BEAM_ACCEL: fx = 0.1fx;
const BEAM_FRAMES: int = 180;

// 源 ECir01_at 的直线激光：出生在发射体位置，沿 %A 以源速度曲线外飞。
// 增长段（initialLength 0）按目标近似为出生即全长判定段，见 report。
async sub beam(h: int, ang: angle, x: fx, y: fx) {
    var px: fx = x;
    var py: fx = y;
    var c: fx = cos(ang);
    var s: fx = sin(ang);
    for t in 0..BEAM_FRAMES {
        var v: fx = BEAM_SPEED;
        if t >= 60 {
            v = BEAM_SPEED + BEAM_ACCEL * ((t - 60) as fx);
        }
        px = px + v * c;
        py = py + v * s;
        lz_origin(h, px, py);
        wait(1);
    }
    lz_cancel(h);   // 源已整体出屏；目标自身不会因平移回收
}

// 源 ECir01_at：%A = ANGLE_PLAYER + F0；每轮 etAngle+laserOn，等待后 %A -= F1（Easy 再减一次）。
async sub fan(f0: angle, f1: angle) {
    var ang: angle = aim_player() + f0;
    if ang >= 180deg { ang = ang - 360deg; }
    if ang < -180deg { ang = ang + 360deg; }
    var count: int = 20;
    var dt: int = 5;
    var step: angle = f1;
    if global(GVAR_RANK) == 0 {
        count = 10;
        dt = 10;
        step = f1 + f1;
    }
    for k in 0..count {
        var h: int = laser(BEAM_COLOR, $self_x, $self_y, ang, BEAM_FAR, BEAM_WIDTH, 0, 400, 0);
        lz_start(h, BEAM_NEAR);
        spawn beam(h, ang, $self_x, $self_y);
        wait(dt);
        ang = ang - step;
        if ang >= 180deg { ang = ang - 360deg; }
        if ang < -180deg { ang = ang + 360deg; }
    }
}

// 源 ECir01：REL 层 (-64,-128) 瞬时写入，60 帧二次减速回 (x,y)；+60 起 ECir01_at。
// +180 wait 后 moveVel(ANGLE_PLAYER,0)+moveSpeedTime(120,0,1.0) 朝自机漂移。
// 出生动画、flagSet(15)/flagClear(15)、掉落与音效按共用口径省略。
async sub ecir01(x: fx, y: fx, f0: angle, f1: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);              // setHurtbox(24,24) → 半径 12
    set_hitbox(8fx);                // setHitbox(16,16) → 半径 8
    move_to(60, x, y, EASE_QUAD_OUT);
    wait(60);
    spawn fan(f0, f1);
    wait(180);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);
    move_speed(120, 1fx, EASE_LINEAR);
    loop { wait(1000); }
}

// 源 MainSub01 898-916：F0/F1 成对快照给各子敌；H/L 与 L 额外发射体逐档保留。
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-192fx, 0fx, 600, 0, 1000, 0, ecir01(-128fx, 128fx, 90deg, 15deg));
    if global(GVAR_RANK) >= 2 {
        _ = spawn_enemy(-32fx, -96fx, 300, 0, 1000, 0, ecir01(32fx, 32fx, 90deg, 15deg));
    }
    if global(GVAR_RANK) >= 3 {
        _ = spawn_enemy(16fx, -48fx, 200, 0, 1000, 0, ecir01(80fx, 80fx, 90deg, 15deg));
    }
    _ = spawn_enemy(64fx, 0fx, 600, 0, 1000, 0, ecir01(128fx, 128fx, -90deg, -15deg));
    if global(GVAR_RANK) >= 2 {
        _ = spawn_enemy(-96fx, -96fx, 300, 0, 1000, 0, ecir01(-32fx, 32fx, -90deg, -15deg));
    }
    if global(GVAR_RANK) >= 3 {
        _ = spawn_enemy(-144fx, -48fx, 200, 0, 1000, 0, ecir01(-80fx, 80fx, -90deg, -15deg));
    }
    wait(150);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
